create or replace function public.get_my_mastery_engine() returns jsonb language sql stable security invoker set search_path='' as $$
with me as(select id,education_stage_key from public.profiles where id=(select auth.uid())), comps as(
 select c.*,coalesce(m.mastery_score,0) mastery_score,coalesce(m.mastery_level,'not_started') mastery_level,coalesce(m.confidence_score,0) confidence_score,coalesce(m.evidence_count,0) evidence_count,coalesce(m.verified_evidence_count,0) verified_evidence_count,m.last_evidence_at
 from public.learning_competencies c cross join me left join public.learner_mastery_records m on m.competency_id=c.id and m.user_id=me.id where c.stage_key=me.education_stage_key and c.content_status<>'retired'
), domains as(select domain_key,domain_title,round(avg(mastery_score),2) score,count(*) competencies,count(*) filter(where mastery_level='mastered') mastered,count(*) filter(where mastery_level in ('not_started','emerging','developing')) needs_growth from comps group by domain_key,domain_title)
select jsonb_build_object('stage_key',(select education_stage_key from me),'overall_score',coalesce((select round(avg(mastery_score),2) from comps),0),'mastered_count',(select count(*) from comps where mastery_level='mastered'),'competency_count',(select count(*) from comps),'domains',coalesce((select jsonb_agg(to_jsonb(d) order by d.score desc) from domains d),'[]'::jsonb),'competencies',coalesce((select jsonb_agg(jsonb_build_object('id',id,'competency_key',competency_key,'domain_key',domain_key,'domain_title',domain_title,'title',title,'description',description,'mastery_score',mastery_score,'mastery_level',mastery_level,'confidence_score',confidence_score,'evidence_count',evidence_count,'verified_evidence_count',verified_evidence_count,'last_evidence_at',last_evidence_at) order by display_order) from comps),'[]'::jsonb),'next_to_learn',coalesce((select jsonb_agg(x) from (select jsonb_build_object('id',id,'title',title,'domain',domain_title,'score',mastery_score,'level',mastery_level) x from comps where mastery_level<>'mastered' order by mastery_score asc,display_order limit 4)q),'[]'::jsonb));
$$;
revoke all on function public.get_my_mastery_engine() from public,anon;grant execute on function public.get_my_mastery_engine() to authenticated,service_role;

create or replace function public.get_my_learner_passport_v2() returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare v_uid uuid:=(select auth.uid());v_p public.profiles%rowtype;v_stage public.education_audience_stages%rowtype;v_mastery jsonb;v_old jsonb;v_name text;v_progress numeric;begin
 if v_uid is null then raise exception 'authentication required';end if;select * into v_p from public.profiles where id=v_uid;if not found then raise exception 'profile not found';end if;select * into v_stage from public.education_audience_stages where stage_key=v_p.education_stage_key;v_mastery:=public.get_my_mastery_engine();begin v_old:=public.get_my_career_passport_summary();exception when others then v_old:='{}'::jsonb;end;
 v_name:=case v_p.education_stage_key when 'school_1_6' then 'Growth Passport' when 'school_7_8' then 'Exploration Passport' when 'school_9_10' then 'Skills Passport' when 'school_11_12' then 'Transition Passport' else 'Career Passport' end;
 v_progress:=least(100,round((coalesce((v_mastery->>'overall_score')::numeric,0)*0.45)+(coalesce((v_old->>'profile_score')::numeric,0)*0.25)+(least(100,(select count(*)*12 from public.learner_projects where user_id=v_uid and status in ('submitted','verified')))*0.15)+(least(100,(select count(*)*10 from public.verified_skills where user_id=v_uid))*0.15),2));
 return jsonb_build_object('passport_name',v_name,'stage_key',v_p.education_stage_key,'stage_title',v_stage.title,'grade_level',v_p.grade_level,'institution_name',v_p.institution_name,'progression_score',v_progress,'mastery',v_mastery,'profile_summary',v_old,'verified_skills',coalesce((select jsonb_agg(to_jsonb(vs) order by vs.verified_at desc) from public.verified_skills vs where vs.user_id=v_uid),'[]'::jsonb),'projects',coalesce((select jsonb_agg(to_jsonb(p) order by p.created_at desc) from (select * from public.learner_projects where user_id=v_uid order by created_at desc limit 12)p),'[]'::jsonb),'achievements',coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at desc) from (select * from public.career_passport_achievements where user_id=v_uid order by created_at desc limit 12)a),'[]'::jsonb),'evidence_summary',jsonb_build_object('mastery_evidence',(select count(*) from public.learner_mastery_evidence where user_id=v_uid),'verified_mastery_evidence',(select count(*) from public.learner_mastery_evidence where user_id=v_uid and verified),'projects',(select count(*) from public.learner_projects where user_id=v_uid),'verified_projects',(select count(*) from public.learner_projects where user_id=v_uid and verified)));
end;$$;
revoke all on function public.get_my_learner_passport_v2() from public,anon;grant execute on function public.get_my_learner_passport_v2() to authenticated,service_role;

create or replace function private.set_my_mela_next_goal(p_goal_type text,p_goal_title text,p_career_path_id uuid default null,p_target_date date default null)
returns public.mela_transition_plans language plpgsql security definer set search_path='' as $$
declare v_uid uuid:=(select auth.uid());v_stage text;v_plan public.mela_transition_plans%rowtype;v_allowed boolean:=false;begin
 if v_uid is null then raise exception 'authentication required';end if;select education_stage_key into v_stage from public.profiles where id=v_uid and role='student';if v_stage is null then raise exception 'learner education stage required';end if;
 v_allowed:=case when v_stage in ('school_1_6','school_7_8') then p_goal_type='next_grade' when v_stage='school_9_10' then p_goal_type in ('next_grade','college_tvet','university','career_path') when v_stage='school_11_12' then p_goal_type in ('college_tvet','university','career_path','scholarship','employment','entrepreneurship') when v_stage in ('college_tvet','university') then p_goal_type in ('career_path','scholarship','employment','entrepreneurship','university','college_tvet') else false end;
 if not v_allowed then raise exception 'goal type is not appropriate for your education stage';end if;
 if p_goal_type='employment' and v_stage='school_11_12' and not exists(select 1 from public.user_policy_acknowledgements a join public.platform_policy_documents d on d.id=a.policy_document_id where a.user_id=v_uid and a.accepted and d.policy_key='adult_work_eligibility' and d.active) then raise exception '18+ work eligibility acknowledgement required';end if;
 update public.mela_transition_plans set status='archived',updated_at=now() where user_id=v_uid and status='active';
 if nullif(trim(p_goal_title),'') is null then raise exception 'goal title required';end if;
 insert into public.mela_transition_plans(user_id,goal_type,goal_title,career_path_id,target_date) values(v_uid,p_goal_type,trim(p_goal_title),p_career_path_id,p_target_date) returning * into v_plan;
 insert into public.mela_transition_steps(plan_id,step_order,step_type,title,description,route_key) values
 (v_plan.id,1,'research','Understand your starting point','Review your Mastery Map and current evidence.','mastery'),
 (v_plan.id,2,'research','Explore possible routes','Use the Opportunity Graph to compare realistic routes.','opportunity-graph'),
 (v_plan.id,3,'project','Build evidence','Complete a project or learning activity that strengthens the capabilities you need.','passport'),
 (v_plan.id,4,'verify','Prove progress','Add verified evidence through Practice, assessment, project review or teacher observation.','passport'),
 (v_plan.id,5,'prepare','Prepare the next move','Prepare applications, scholarship materials, placement evidence or the next education step.','mela-next');return v_plan;end;$$;
revoke all on function private.set_my_mela_next_goal(text,text,uuid,date) from public,anon,authenticated;
create or replace function public.set_my_mela_next_goal(p_goal_type text,p_goal_title text,p_career_path_id uuid default null,p_target_date date default null) returns public.mela_transition_plans language sql set search_path='' as $$select * from private.set_my_mela_next_goal(p_goal_type,p_goal_title,p_career_path_id,p_target_date);$$;
revoke all on function public.set_my_mela_next_goal(text,text,uuid,date) from public,anon;grant execute on function public.set_my_mela_next_goal(text,text,uuid,date) to authenticated,service_role;

create or replace function public.get_my_opportunity_graph() returns jsonb language sql stable security invoker set search_path='' as $$
with me as(select education_stage_key from public.profiles where id=(select auth.uid())),start as(select id from public.opportunity_graph_nodes where node_key='stage:'||(select education_stage_key from me)),first_edges as(select e.* from public.opportunity_graph_edges e join start s on s.id=e.from_node_id where e.active),first_nodes as(select n.* from public.opportunity_graph_nodes n join first_edges e on e.to_node_id=n.id where n.active),second_edges as(select e.* from public.opportunity_graph_edges e join first_nodes n on n.id=e.from_node_id where e.active),ids as(select id from start union select id from first_nodes union select to_node_id from second_edges),edges as(select id,from_node_id,to_node_id,relationship,weight,rationale,active from first_edges union select id,from_node_id,to_node_id,relationship,weight,rationale,active from second_edges)
select jsonb_build_object('stage_key',(select education_stage_key from me),'nodes',coalesce((select jsonb_agg(jsonb_build_object('id',n.id,'node_key',n.node_key,'node_type',n.node_type,'title',n.title,'description',n.description,'route_key',n.route_key,'metadata',n.metadata)) from public.opportunity_graph_nodes n where n.id in(select id from ids)),'[]'::jsonb),'edges',coalesce((select jsonb_agg(jsonb_build_object('from',e.from_node_id,'to',e.to_node_id,'relationship',e.relationship,'weight',e.weight,'rationale',e.rationale)) from edges e),'[]'::jsonb),'real_opportunities',jsonb_build_object('open',(select count(*) from public.opportunities where status='open' and verified_active),'scholarships',(select count(*) from public.opportunities where status='open' and verified_active and opportunity_type='scholarships')));
$$;
revoke all on function public.get_my_opportunity_graph() from public,anon;grant execute on function public.get_my_opportunity_graph() to authenticated,service_role;

create or replace function public.get_my_mela_next() returns jsonb language sql stable security invoker set search_path='' as $$select jsonb_build_object('audience',public.get_my_audience_context(),'mastery',public.get_my_mastery_engine(),'graph',public.get_my_opportunity_graph(),'active_plan',coalesce((select to_jsonb(p) from public.mela_transition_plans p where p.user_id=(select auth.uid()) and p.status='active' limit 1),'null'::jsonb),'steps',coalesce((select jsonb_agg(to_jsonb(s) order by s.step_order) from public.mela_transition_steps s join public.mela_transition_plans p on p.id=s.plan_id where p.user_id=(select auth.uid()) and p.status='active'),'[]'::jsonb),'career_paths',coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'category',category,'description',description,'badge_title',badge_title) order by category,title) from public.career_paths),'[]'::jsonb));$$;
revoke all on function public.get_my_mela_next() from public,anon;grant execute on function public.get_my_mela_next() to authenticated,service_role;

